const feat=x=>[1,x[0]/1500,x[1]/8,x[2]/60,x[0]*x[0]/2250000,x[1]*x[1]/64,x[0]*x[1]/12000,x[0]*x[2]/90000];function data(n,seed){let R=rng(seed);return Array.from({length:n},()=>{let x=[600+1600*R(),1+7*R(),30+40*R()],q=x[0]/1000,y=80+260*q-62*q*q+16*x[1]-2*x[1]*x[1]+.45*x[2]-1.1*q*x[2]+(R()-.5)*12;return{x,y};});}
